/*
 * A025058  Numbers of form i*j + j*k + k*i, where 1 <=i < j < k, including
 *          repetitions.
 * https://oeis.org/A025058
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth element (1‑indexed) of the multiset { i*j + j*k +
 *            k*i | 1 ≤ i < j < k }, sorted nondecreasing. Implementation uses
 *            a priority queue that merges the arithmetic progressions
 *            generated by each pair (i,j). Only pairs with i ≤ 200 and j ≤
 *            i+200 are considered; this is sufficient to prod...
 * Range:     u8 none, u16 none, u32 n <= 2000, u64 n <= 2000, u128 n <= 2000,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* ------------------------------------------------------------------ */
/* Helper structures and constants                                    */
typedef struct {
    seq_t val;   /* current value i*j + j*k + k*i */
    idx_t i;     /* fixed i  */
    idx_t j;     /* fixed j  */
    idx_t k;     /* current k   */
} Node;

#define I_MAX      200     /* maximum i considered                 */
#define J_OFFSET   200     /* for each i, j ranges up to i+J_OFFSET */
#define MAX_CACHE  20000   /* maximum number of terms cached     */

static Node heap[ I_MAX * J_OFFSET ];
static size_t heap_size = 0;             /* current number of heap elements */
static seq_t cache[ MAX_CACHE ];         /* cached terms */
static size_t cache_len = 0;             /* number of terms generated */

/* ------------------------------------------------------------------ */
/* Heap manipulation functions                                          */
static void heap_swap(Node *a, Node *b) {
    Node tmp = *a;
    *a = *b;
    *b = tmp;
}

static void heapify_up(size_t idx) {
    while (idx > 0) {
        size_t parent = (idx - 1) >> 1;
        if (heap[parent].val <= heap[idx].val) break;
        heap_swap(&heap[parent], &heap[idx]);
        idx = parent;
    }
}

static void heapify_down(size_t idx) {
    size_t size = heap_size;
    while (1) {
        size_t left  = (idx << 1) + 1;
        size_t right = left + 1;
        size_t smallest = idx;
        if (left < size && heap[left].val < heap[smallest].val)
            smallest = left;
        if (right < size && heap[right].val < heap[smallest].val)
            smallest = right;
        if (smallest == idx) break;
        heap_swap(&heap[idx], &heap[smallest]);
        idx = smallest;
    }
}

static Node heap_pop(void) {
    Node min = heap[0];
    if (--heap_size > 0) {
        heap[0] = heap[heap_size];
        heapify_down(0);
    }
    return min;
}

static void heap_push(Node n) {
    heap[heap_size++] = n;
    heapify_up(heap_size - 1);
}

/* ------------------------------------------------------------------ */
/* Initialization of the heap                                           */
static void init_heap(void) {
    size_t pos = 0;
    for (idx_t i = 1; i <= I_MAX; ++i) {
        for (idx_t j = i + 1; j <= i + J_OFFSET; ++j) {
            idx_t k = j + 1;
            seq_t val = (seq_t)i * j + (seq_t)j * k + (seq_t)k * i;
            heap[pos++] = (Node){ val, i, j, k };
        }
    }
    heap_size = pos;
    /* Build min‑heap */
    for (size_t idx = (heap_size >> 1); idx-- > 0;) {
        heapify_down(idx);
    }
}

/* ------------------------------------------------------------------ */
/* Main sequence function                                               */
seq_t a(idx_t n)
{
    if (n < 1) return 0;          /* undefined, but safe */

    /* Initialize on first call */
    if (cache_len == 0) {
        init_heap();
    }

    /* Generate terms until we have at least n */
    while (cache_len < (size_t)n) {
        Node cur = heap_pop();           /* smallest pending term */
        cache[cache_len++] = cur.val;    /* store it */

        /* Advance this sequence: k++, val += i + j */
        cur.k++;
        cur.val += (seq_t)(cur.i + cur.j);
        heap_push(cur);
    }

    return cache[n - 1];
}
